private val SELECTABLE = setOf("id", "email", "created_at")

fun project(user: User, fields: List<String>): JsonObject {
    val unknown = fields.filterNot(SELECTABLE::contains)
    require(unknown.isEmpty()) { "unknown fields: $unknown" }
    return Json.encodeToJsonElement(user).jsonObject.filterKeys { it in fields }
}

