private val SELECTABLE = setOf("id", "email", "created_at")

fun project(user: User, fields: List<String>): JsonObject {
    val unknown = fields.filterNot(SELECTABLE::contains)
    require(unknown.isEmpty()) { "unknown fields: $unknown" }
    return Json.encodeToJsonElement(user).jsonObject.filterKeys { it in fields }
}

@Serializable data class UserCard(val id: String, val email: String)
@Serializable data class UserFull(val id: String, val email: String, val createdAt: String)

fun viewOf(user: User, fields: Set<String>): Any = when (fields) {
    setOf("id", "email") -> UserCard(user.id, user.email)
    setOf("id", "email", "created_at") -> UserFull(user.id, user.email, user.createdAt)
    else -> throw BadRequestException("unsupported selection: $fields")
}
